package org.eclipse.rdf4j.sail.lmdb.bulk;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.sail.SailConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** The bulk loader's default statement indexes, used when the configuration names none. */
class LmdbBulkLoaderDefaultIndexesTest {

	@TempDir
	Path temporaryDirectory;

	@Test
	void theDefaultIndexListIncludesOspc() {
		assertThat(StatementIndexBulkRecords.parseSpecifications(null)).containsExactly("spoc", "posc", "ospc");
		assertThat(StatementIndexBulkRecords.parseSpecifications(" ")).containsExactly("spoc", "posc", "ospc");
	}

	@Test
	void aBulkLoadWithoutConfiguredIndexesBuildsOspc() throws Exception {
		Path target = temporaryDirectory.resolve("store");
		String data = "<urn:s1> <urn:p> <urn:o> .\n<urn:s2> <urn:p> <urn:o> .\n<urn:s2> <urn:q> <urn:other> .\n";
		LmdbBulkLoader.builder(target, new LmdbStoreConfig())
				.build()
				.load(new ByteArrayInputStream(data.getBytes(StandardCharsets.UTF_8)), "urn:input:",
						RDFFormat.NTRIPLES);

		LmdbStore store = new LmdbStore(target.toFile(), new LmdbStoreConfig());
		store.init();
		try {
			assertThat(store.getLmdbStats().tripleDatabases().keySet())
					.contains("spocspoc", "poscposc", "ospcospc");
			assertThat(store.getLmdbStats().tripleDatabases().get("ospcospc").entries()).isEqualTo(3);
			SimpleValueFactory vf = SimpleValueFactory.getInstance();
			try (SailConnection connection = store.getConnection();
					var statements = connection.getStatements(null, null, vf.createIRI("urn:o"), false)) {
				assertThat(statements.stream().count()).isEqualTo(2);
			}
		} finally {
			store.shutDown();
		}
	}
}
